export function App() {
  return (
    <main aria-label="DEVNS workbench">
      <h1>Feature queue</h1>
      <section data-testid="review-packets">Review packets</section>
      <section data-testid="artifact-digest">Artifact digest</section>
    </main>
  );
}

import fs from 'node:fs';
import path from 'node:path';

const source = fs.readFileSync(path.join(process.cwd(), 'src/App.tsx'), 'utf8');
const semanticSnapshot = ['Feature queue', 'Review packets', 'Artifact digest'].filter((text) => source.includes(text));
const artifact = {
  projectType: 'react-vite',
  landmark: source.includes('<main') ? 'main' : 'missing',
  accessibilityName: source.includes('aria-label="DEVNS workbench"') ? 'DEVNS workbench' : 'missing',
  semanticSnapshot: semanticSnapshot.join(' | ')
};
const outDir = path.join(process.cwd(), '.devns/artifacts/t3');
fs.mkdirSync(outDir, { recursive: true });
fs.writeFileSync(path.join(outDir, 'vite-surface.json'), JSON.stringify(artifact, null, 2) + '\n');
